```sol
// Solidity Mitigation Example
function batchGrantRoles(
    address[] memory accounts,
    uint32[] memory roleGrantedTimestamps,
    uint256 batchSize
) external onlyBorrower {
    uint256 len = accounts.length;
    require(batchSize > 0 && batchSize <= len, "Invalid batch size");

    uint256 startIndex = 0;
    while (startIndex < len) {
        uint256 endIndex = startIndex + batchSize;
        if (endIndex > len) {
            endIndex = len;
        }

        for (uint256 i = startIndex; i < endIndex; i++) {
            _grantRole(_roleProviders[msg.sender], accounts[i], roleGrantedTimestamps[i]);
        }

        startIndex = endIndex;
    }
